  }
  subscriptions.add(uri);
  return { subscribed: true };
}

export async function unsubscribeResource(uri) {
  if (typeof uri !== 'string' || uri.length === 0) {
    throw makeError(-32602, 'uri is required and must be a non-empty string');
  }
  if (!subscriptions.has(uri)) {
    throw makeError(-32602, 'not subscribed to uri: ' + uri);
  }
  subscriptions.delete(uri);
  return { unsubscribed: true };
}

export async function listTools() {
  return [
    {
      name: 'subscribeResource',
      description: 'Subscribe to a resource by URI. Duplicate subscriptions are rejected.',
      inputSchema: {
        type: 'object',
        properties: {
          uri: { type: 'string', description: 'The non-empty resource URI to subscribe to.' }
        },
        required: ['uri'],
        additionalProperties: false
      }
    },
    {
      name: 'unsubscribeResource',
      description: 'Unsubscribe from a resource by URI. Rejects subscriptions that do not exist.',
      inputSchema: {
        type: 'object',
        properties: {
          uri: { type: 'string', description: 'The resource URI to unsubscribe from.' }
        },
        required: ['uri'],
        additionalProperties: false
      }
    }
