import('./server.mjs').then(async m => {
  // Test subscribe returns subscribed true
  const r1 = await m.subscribeResource('res://x');
  console.log('subscribe:', JSON.stringify(r1));

  // Test duplicate rejection
  try { await m.subscribeResource('res://x'); console.log('ERROR: duplicate allowed'); }
  catch(e) { console.log('duplicate rejected:', e.message); }

  // Test unsubscribe returns unsubscribed true
  const r2 = await m.unsubscribeResource('res://x');
  console.log('unsubscribe:', JSON.stringify(r2));

  // Test missing subscription rejection
  try { await m.unsubscribeResource('res://missing'); console.log('ERROR: missing allowed'); }
  catch(e) { console.log('missing rejected:', e.message); }

  // Test empty uri rejection
  try { await m.subscribeResource(''); console.log('ERROR: empty allowed'); }
  catch(e) { console.log('empty uri rejected:', e.message); }
});
""}

